DELETE FROM host_asset_inventory
WHERE host_id = #{hostId}
  AND task_id = #{taskId}

mapper.select:
SELECT MAX(hai.id) AS id, hai.tenant_id, hai.host_id, MAX(hai.mac_address) AS mac_address, hai.task_id, MAX(hai.source) AS source, MAX(hai.category) AS category, MAX(hai.sub_category) AS sub_category, MAX(hai.vendor) AS vendor, NULL AS port, NULL AS product_version, MAX(hai.protocol) AS protocol, CONCAT('Port Assets Task #', hai.task_id) AS product_name, 'port-task' AS product_type, COUNT(1) AS confidence, NULL AS rule_id, NULL AS banner_raw, MAX(hai.deleted) AS deleted, MIN(hai.first_seen) AS first_seen, MAX(hai.last_seen) AS last_seen, MIN(hai.created_at) AS created_at, MAX(hai.updated_at) AS updated_at FROM host_asset_inventory hai JOIN hosts h ON h.id = hai.host_id WHERE hai.tenant_id = #{tenantId} AND h.tenant_id = #{tenantId} AND (hai.deleted = 0 OR hai.deleted IS NULL)
AND ( h.hostname LIKE CONCAT('%', #{keyword}, '%') OR h.mac_address LIKE CONCAT('%', #{keyword}, '%') OR hai.task_id LIKE CONCAT('%', #{keyword}, '%') OR CAST(hai.port AS CHAR) LIKE CONCAT('%', #{keyword}, '%') OR hai.product LIKE CONCAT('%', #{keyword}, '%') OR hai.category LIKE CONCAT('%', #{keyword}, '%') OR hai.sub_category LIKE CONCAT('%', #{keyword}, '%') )
AND h.mac_address = #{macAddress}
GROUP BY hai.tenant_id, hai.host_id, hai.task_id ORDER BY MAX(hai.updated_at) DESC, MAX(hai.id) DESC LIMIT #{size} OFFSET #{offset}

SELECT 
FROM host_asset_inventory hai
WHERE hai.host_id = #{hostId}
  AND hai.task_id = #{taskId}
  AND hai.tenant_id = #{tenantId}
  AND (hai.deleted = 0 OR hai.deleted IS NULL)
ORDER BY hai.port ASC, hai.id ASC

SELECT 
FROM host_asset_inventory hai
JOIN hosts h ON h.id = hai.host_id
WHERE hai.tenant_id = #{tenantId}
  AND h.tenant_id = #{tenantId}
  AND (hai.deleted = 0 OR hai.deleted IS NULL)

      AND (
          h.hostname LIKE CONCAT('%', #{keyword}, '%')
          OR h.mac_address LIKE CONCAT('%', #{keyword}, '%')
          OR hai.product LIKE CONCAT('%', #{keyword}, '%')
          OR hai.category LIKE CONCAT('%', #{keyword}, '%')
      )


      AND h.mac_address = #{macAddress}

ORDER BY hai.updated_at DESC, hai.id DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(1)
FROM host_asset_inventory hai
JOIN hosts h ON h.id = hai.host_id
WHERE hai.tenant_id = #{tenantId}
  AND h.tenant_id = #{tenantId}
  AND (hai.deleted = 0 OR hai.deleted IS NULL)

      AND (
          h.hostname LIKE CONCAT('%', #{keyword}, '%')
          OR h.mac_address LIKE CONCAT('%', #{keyword}, '%')
          OR hai.product LIKE CONCAT('%', #{keyword}, '%')
          OR hai.category LIKE CONCAT('%', #{keyword}, '%')
      )


      AND h.mac_address = #{macAddress}

SELECT 
FROM host_asset_inventory hai
WHERE hai.id = #{id}
  AND hai.tenant_id = #{tenantId}
  AND (hai.deleted = 0 OR hai.deleted IS NULL)

SELECT 
FROM host_asset_inventory hai
JOIN hosts h ON h.id = hai.host_id
WHERE hai.tenant_id = #{tenantId}
  AND h.tenant_id = #{tenantId}
  AND (hai.deleted = 0 OR hai.deleted IS NULL)
  AND h.mac_address = #{macAddress}
ORDER BY hai.updated_at DESC, hai.id DESC
LIMIT 1

